use std::future::Future;

async fn load_name(id: u64) -> Result<String, String> {
    let name = async { format!("User-{id}") }.await;
    if id == 0 { return Err("Missing user".into()); }
    Ok(name)
}

fn greeting(id: u64) -> impl Future<Output = Result<String, String>> {
    async move {
        let name = load_name(id).await?;
        Ok(format!("Welcome, {name}"))
    }
}

fn main() {
    // The future is lazy; an application supplies its own executor.
    let future = greeting(42);
    drop(future);
}

#[unsafe(no_mangle)]
pub extern "C" fn add_one(value: u32) -> u32 {
    value + 1
}

struct Buffer<const N: usize> {
    values: [u8; N],
}

fn is_ready(value: Option<u32>) -> bool {
    if let Some(found) = value && found > 3 {
        true
    } else {
        false
    }
}

fn main() {
    let r#gen = Buffer { values: [1, 2, 3, 4] };
    assert!(is_ready(Some(add_one(4))));
    println!("{} bytes", r#gen.values.len());
}

#[derive(Debug, Clone)]
struct User {
    name: String,
    score: u32,
}

impl User {
    fn new(name: &str) -> Self {
        Self { name: name.to_owned(), score: 0 }
    }

    fn greet(&self) -> String {
        format!("Hello, {}!", self.name)
    }
}

fn main() {
    let mut user = User::new("Ada");
    user.score += 10;
    println!("{} Score: {}", user.greet(), user.score);
}

macro_rules! list {
    ($($value:expr),* $(,)?) => {
        vec![$($value),*]
    };
}

macro_rules! announce {
    ($label:expr, $value:expr) => {
        println!("{} = {:?}", $label, $value)
    };
}

fn main() {
    let values = list![2, 4, 8,];
    let doubled: Vec<_> = values.iter().map(|value| value * 2).collect();
    announce!("doubled", doubled);
    assert_eq!(doubled.len(), 3);
}

fn longest<'a>(left: &'a str, right: &'a str) -> &'a str {
    if left.len() >= right.len() { left } else { right }
}

fn first<T>(items: &[T]) -> Option<&T> {
    items.first()
}

fn main() {
    let owned = String::from("Ownership");
    let borrowed = &owned;
    let names = [borrowed.as_str(), "Rust"];

    if let Some(name) = first(&names) {
        println!("{}", longest(name, "Virgo"));
    }
}

#[derive(Debug)]
enum Message {
    Quit,
    Move { x: i32, y: i32 },
    Text(String),
}

fn handle(message: Message) -> String {
    match message {
        Message::Quit => "Goodbye".into(),
        Message::Move { x, y } if x == y => format!("Diagonal: {x}"),
        Message::Move { x, y } => format!("Position: {x}, {y}"),
        Message::Text(text) => text.to_uppercase(),
    }
}

fn main() {
    let messages = [Message::Move { x: 3, y: 3 }, Message::Text("Ready".into()), Message::Quit];
    for message in messages {
        println!("{}", handle(message));
    }
}

fn main() {
    // Original Unicode, escapes and delimiters stay unchanged.
    let document = r##"{ "title": "星空 🌌", "path": "C:\notes" }"##;
    let request = br#"GET / HTTP/1.1"#;
    let label = c"ready";
    let symbol = '星';
    let escaped = '\n';
    let mask = 0xff_u32;

    /* A block comment can contain /* another comment */ safely. */
    println!("{document} {request:?} {label:?} {symbol} {escaped} {mask:x}");
}

trait Summarize {
    fn summary(&self) -> String;
}

struct Article<T> {
    title: String,
    content: T,
}

impl<T: std::fmt::Display> Summarize for Article<T> {
    fn summary(&self) -> String {
        format!("{}: {}", self.title, self.content)
    }
}

fn print_summary(item: &impl Summarize) {
    println!("{}", item.summary());
}

fn main() {
    let article = Article { title: "Stable Rust".into(), content: 42 };
    print_summary(&article);
}
